// In-app audible cues (expo-audio). Native, so not unit-tested; verify in the
// Simulator or on device. Two short sine beeps generated by
// `scripts/generate-cue-sounds.mjs`.
import { createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import type { AudioPlayer } from 'expo-audio';
import type { CueKind } from './cues';
import { getCuesInSilentMode } from './timer-settings';

const SOURCES = {
  stage: require('../../../assets/sounds/cue-stage.wav'),
  agitate: require('../../../assets/sounds/cue-agitate.wav'),
} satisfies Record<CueKind, number>;

const players = new Map<CueKind, AudioPlayer>();

function playerFor(kind: CueKind): AudioPlayer {
  let player = players.get(kind);
  if (!player) {
    player = createAudioPlayer(SOURCES[kind]);
    players.set(kind, player);
  }
  return player;
}

/** Play a cue sound, mixing with whatever else is playing. Never throws. */
export async function playCue(kind: CueKind): Promise<void> {
  try {
    await setAudioModeAsync({
      playsInSilentMode: getCuesInSilentMode(),
      interruptionMode: 'mixWithOthers',
      shouldPlayInBackground: false,
    });
    const player = playerFor(kind);
    await player.seekTo(0);
    player.play();
  } catch {
    // Audio is an extra on top of haptics; a failure must not break the run.
  }
}
